                if cmap:
                    seeds.append(cmap)
            except Exception:
                pass

            # --- Seed D: zero-priced-reuse sequential Dijkstra ---
            # Route dsts one at a time; every directed edge already used by
            # an earlier dst in the sequence costs 0, so later dsts pay only
            # genuinely new edges. This directly encodes the union-cost
            # objective at construction time and permits non-tree
            # reconvergent unions. Try several deterministic orderings and
            # keep the cheapest union; then one cleanup pass re-routes each
            # dst in fixed order under the same zero-pricing, accepting a
            # reroute only if the total union cost strictly drops.
            try:
                routable = [d for d in dsts if d != src and d in U]
                if routable:
                    def seq_route(order):
                        used = set()
                        pmap_o = {}
                        for d in order:
                            def zw(u, v, ed):
                                return 0.0 if (u, v) in used else dcost(u, v)
                            try:
                                p = nx.dijkstra_path(h, src, d, weight=zw)
                            except (nx.NetworkXNoPath, nx.NodeNotFound):
                                continue
